fn place(arr: Vec<f32>, mask: Vec<bool>, vals: Vec<f32>) -> Vec<f32> {
    // It's assumed that `arr.len() == mask.len()` and `!vals.is_empty()`.
    let mut result = Vec::with_capacity(arr.len());
    let mut val_idx = 0;

    for (a, m) in arr.into_iter().zip(mask.into_iter()) {
        if m {
            // Take the next replacement value, wrapping around if necessary
            result.push(vals[val_idx]);
            val_idx += 1;
            if val_idx >= vals.len() {
                val_idx = 0;
            }
        } else {
            // Preserve the original value
            result.push(a);
        }
    }

    result
}

