        let mask = vec![false, true, true, false, true];
        let vals = vec![10.0, 20.0];
        // mask:   F    T     T    F    T
        // result: 1  10.0  20.0   4   10.0  (vals wraps)
        let result = place(arr, mask, vals);
        assert_eq!(result, vec![1.0, 10.0, 20.0, 4.0, 10.0]);
